const Advertisment=require("../models/advertismentModel"),Challenge=require("../models/challengesModel"),Event=require("../models/eventsModel"),moment=require("moment"),get_advertisments=async()=>{var e=await Advertisment.aggregate([{$sample:{size:10}}]);return{bestOffersAds:e.filter(e=>"bestOffers"==e.advertiseAt),advertisments:e.filter(e=>"websitePages"==e.advertiseAt),videoAds:e.filter(e=>"videoAds"==e.advertiseAt)}},get_events=async()=>{var e=moment(new Date).format("YYYY-MM-DD");return await Event.aggregate([{$match:{active:!0,endDate:{$gt:e}}},{$sample:{size:10}}])},get_challenges=async()=>{var e=await Challenge.aggregate([{$sample:{size:30}}]);return{playersChallenges:e.filter(e=>"playersChallenge"===e.type).slice(0,5),nationalTeamsChallenge:e.filter(e=>"nationalTeamsChallenge"===e.type).slice(0,5),teamsChallenge:e.filter(e=>"teamsChallenge"===e.type).slice(0,5),homeChallenges:e.slice(0,5)}},inital_fetch=async(e,t,a)=>{var s=await get_advertisments(),l=await get_events(),n=await get_challenges();t.status(200).send({advertisments:s,events:l,challenges:n,lowestBuildNumber:"25"})};module.exports={inital_fetch:inital_fetch};